#[path="../setup/fast.rs"]mod fast;
#[path="../batched/inverse.rs"]mod inverse;
use hec_native_ic::{counted,jac::Curve,fp::Fp,poly::Poly,oracle::{split_reference,OracleStats,Roots}};
use std::{collections::BTreeMap,fs};
type Point=(u64,u64);type Out=Vec<(Poly,Poly,Option<Roots>)>;
fn u_for(p:&[Point;3],c:&Curve)->Poly{p.iter().fold(Poly::one(),|u,&(x,_)|u.mul(&Poly::x_minus(x,&c.fp),&c.fp))}
fn four(p:&Poly,c:&Curve)->Poly{Poly::from_coeffs(&p.c[..p.n].iter().map(|&x|{let x=c.fp.add(x,x);c.fp.add(x,x)}).collect::<Vec<_>>())}
fn cross(a:u64,b:u64,x:u64,c:&Curve)->Poly{let q=c.fp.mul(a,b);Poly::from_coeffs(&[c.fp.neg(c.fp.mul(q,x)),q])}
fn shared(c:&Curve,pts:&[Point],correction:bool)->Out{let f=&c.fp;let mut values=vec![];for i in 0..6{for j in i+1..6{let d=f.sub(pts[i].0,pts[j].0);assert_ne!(d,0);values.push(d);}}let inverses=inverse::invert(&values,f);let mut iv=[[0u64;6];6];let mut t=0;for i in 0..6{for j in i+1..6{iv[i][j]=inverses[t];iv[j][i]=f.neg(inverses[t]);t+=1;}}let mut out=vec![];
for i in 1..6{for j in i+1..6{let p=[pts[0],pts[i],pts[j]];let indices=[0,i,j];let mut gamma=[0;3];let mut part=[Poly::zero();3];for a in 0..3{let mut basis=Poly::one();let mut w=p[a].1;for b in 0..3{if a!=b{basis=basis.mul(&Poly::x_minus(p[b].0,f),f);w=f.mul(w,iv[indices[a]][indices[b]]);}}gamma[a]=w;part[a]=basis.scale(w,f);}let a=part[0];let b=part[1];let d=part[2];let vpp=a.add(&b,f).add(&d,f);let u=u_for(&p,c);let hpp=c.f.sub(&vpp.mul(&vpp,f),f).div_exact(&u,f);let vs=[vpp,a.add(&b,f).sub(&d,f),a.sub(&b,f).add(&d,f),a.sub(&b,f).sub(&d,f)];
let hs=if correction {let ab=cross(gamma[0],gamma[1],p[2].0,c);let ad=cross(gamma[0],gamma[2],p[1].0,c);let bd=cross(gamma[1],gamma[2],p[0].0,c);[hpp,hpp.add(&four(&ad.add(&bd,f),c),f),hpp.add(&four(&ab.add(&bd,f),c),f),hpp.add(&four(&ab.add(&ad,f),c),f)]}else{let mut hs=[hpp;4];for k in 1..4{hs[k]=c.f.sub(&vs[k].mul(&vs[k],f),f).div_exact(&u,f);}hs};
for k in 0..4{let mut stats=OracleStats::default();let roots=split_reference(&hs[k],f,&mut stats);out.push((vs[k],hs[k],roots));}}}out}
fn main(){counted::disable();let mut triggers=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/affine-promotion/CONTROL.stderr").unwrap().lines().filter(|l|l.starts_with("PROMOTE\t")){let v:Vec<_>=l.split('\t').collect();let n=|j:usize|v[j].parse::<u64>().unwrap();if n(7)!=0&&v[9]=="false"{triggers.entry((n(1),n(2))).or_insert(n(5)as usize);}}
println!("p\tsm\trep\tarm\tmodulus\tsplit\tcounts");let(mut calls,mut checked)=(0,0);for(p,cc)in[(101,2),(251,18),(601,7)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z,_)=fast::prepare(&c);let mut reps=vec![];let mut seen=vec![false;fb.len()];for j in 0..fb.len(){if seen[j]{continue}reps.push(j);let mut x=fb[j].0;for _ in 0..5{let k=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert!(!seen[k]);seen[k]=true;x=c.fp.mul(x,z);}}for sm in [1,17]{let Some(&r)=triggers.get(&(p,sm))else{eprintln!("no_trigger p={p} sm={sm}");continue};let mut pts=vec![fb[reps[r]]];let mut x=fb[0].0;for _ in 0..5{pts.push((x,fb[0].1));x=c.fp.mul(x,z);}let mut prior=BTreeMap::new();for rep in 0..2{let mut outputs=vec![None,None];for n in 0..2{let arm=if rep==0{n}else{1-n};counted::reset();let out=shared(&c,&pts,arm==1);let counts=counted::snapshot();counted::disable();assert_eq!(out.len(),40);let split=out.iter().filter(|x|x.2.is_some()).count();let mut index=0;for i in 1..6{for j in i+1..6{let u=u_for(&[pts[0],pts[i],pts[j]],&c);for _ in 0..4{let(v,h,_)=out[index];assert_eq!(h.deg(),2);assert_eq!(h.mul(&u,&c.fp),c.f.sub(&v.mul(&v,&c.fp),&c.fp));index+=1;checked+=1;}}}let sig=(out.clone(),counts.clone());if rep==1{assert_eq!(prior[&arm],sig)}else{prior.insert(arm,sig);}for(modulus,v)in counts{assert_eq!(modulus,p);assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{rep}\t{arm}\t{modulus}\t{split}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}outputs[arm]=Some(out);calls+=1;}assert_eq!(outputs[0],outputs[1]);}}}assert_eq!(calls,20);assert_eq!(checked,800);eprintln!("calls={calls} qualified_signed_outputs={checked} all_v_H_roots_identical=true repeats_exact=true preparation_and_quadratic_splitting_charged=true");}
